#!/usr/bin/env python3"""Миграция для добавления поля is_system_chat_hidden в таблицу user"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)import sqlite3from pathlib import Pathdef migrate_database():    """Добавляет поле is_system_chat_hidden в таблицу user"""        # Путь к базе данных    db_path = Path(__file__).parent / "database.db"        if not db_path.exists():        print(f"База данных не найдена: {db_path}")        return False        try:        # Подключаемся к базе данных        conn = sqlite3.connect(db_path)        cursor = conn.cursor()                # Проверяем, существует ли уже поле        cursor.execute("PRAGMA table_info(user)")        columns = [column[1] for column in cursor.fetchall()]                if 'is_system_chat_hidden' in columns:            print("Поле is_system_chat_hidden уже существует")            return True                # Добавляем поле        cursor.execute("""            ALTER TABLE user             ADD COLUMN is_system_chat_hidden BOOLEAN DEFAULT 0        """)                # Обновляем существующих пользователей (устанавливаем значение по умолчанию)        cursor.execute("""            UPDATE user             SET is_system_chat_hidden = 0             WHERE is_system_chat_hidden IS NULL        """)                # Сохраняем изменения        conn.commit()                print("Миграция успешно выполнена: добавлено поле is_system_chat_hidden")        return True            except Exception as e:        print(f"Ошибка при выполнении миграции: {e}")        conn.rollback()        return False            finally:        conn.close()if __name__ == "__main__":    migrate_database()